      "attrs": {
        "d": "M4 9h8v-3.586a1 1 0 0 1 1.707 -.707l6.586 6.586a1 1 0 0 1 0 1.414l-6.586 6.586a1 1 0 0 1 -1.707 -.707v-3.586h-8a1 1 0 0 1 -1 -1v-4a1 1 0 0 1 1 -1"
      }
    }
  ],
  "accents": []
};

export const meta = {
  "slug": "tabler-arrow-big-right",
  "family": "tabler",
  "name": "arrow-big-right",
  "category": "Navigation",
  "motion": "slideRight",
  "component": "createTablerArrowBigRightIcon"
};

export function createTablerArrowBigRightIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
